{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { evaluateAll, depsOf, formatValue } from './eval.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')
let cells
try {
  cells = parseSheet(input)
} catch (e) {
  if (e && e.sheetError) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  throw e
}

let out = ''
if (mode === 'values') {
  const vals = evaluateAll(cells)
  for (const c of cells) out += `${c.addr}=${formatValue(vals.get(c.addr))}\n`
} else {
  for (const c of cells) out += `${c.addr}:${depsOf(c).map((a) => ' ' + a).join('')}\n`
}
process.stdout.write(out)
"}

{"file_path":"src/sheet.js","content":"export function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  let col
  if (L.length === 1) col = L.charCodeAt(0) - 64
  else col = 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row, key: L + row }
}

function fail(msg) {
  const e = new Error(msg)
  e.sheetError = true
  return e
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const seen = new Set()
  const cells = []
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
    const word = m[1]
    const a = parseAddr(word)
    if (!a) throw fail(`error: line ${i + 1}: invalid cell address ${word}`)
    if (seen.has(a.key)) throw fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
    seen.add(a.key)
    cells.push({ addr: a.key, col: a.col, row: a.row, content: m[2] })
  })
  cells.sort((x, y) => x.col - y.col || x.row - y.row)
  return cells
}
