    if (p >= toks.length) throw new Bad()
    const t = toks[p]
    if (t.t === 'num') { p++; return { k: 'num', v: Number(t.v) } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      expect(')')
      return { k: 'group', e }
    }
    if (t.t === 'word') {
      p++
      if (peekOp('(')) {
        p++
