{"file_path":"src/sheet.js","content":"export function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  let col
  if (L.length === 1) col = L.charCodeAt(0) - 64
  else col = 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row, key: L + row }
}

function fail(msg) {
  const e = new Error(msg)
  e.sheetError = true
  return e
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const seen = new Set()
  const cells = []
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
    const word = m[1]
    const a = parseAddr(word)
    if (!a) throw fail(`error: line ${i + 1}: invalid cell address ${word}`)
    if (seen.has(a.key)) throw fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
    seen.add(a.key)
    cells.push({ addr: a.key, col: a.col, row: a.row, content: m[2] })
  })
  cells.sort((x, y) => x.col - y.col || x.row - y.row)
  return cells
}
"}

{"file_path":"src/eval.js","content":"import { parseAddr } from './sheet.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ err: e })
const isErr = (v) => typeof v === 'object'
const NUM_RE = /^-?[0-9]+(\.[0-9]+)?$/

// ---------- parsing ----------
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: m[0] }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

class Bad extends Error {}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peekOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const expect = (v) => { if (!peekOp(v)) throw new Bad(); p++ }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp('+') || peekOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw new Bad()
    const t = toks[p]
    if (t.t === 'num') { p++; return { k: 'num', v: Number(t.v) } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      expect(')')
      return { k: 'group', e }
    }
    if (t.t === 'word') {
      p++
      if (peekOp('(')) {
        p++
        const args = []
        if (!peekOp(')')) {
          args.push(cmp())
          while (peekOp(',')) { p++; args.push(cmp()) }
        }
        expect(')')
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      const up = t.v.toUpperCase()
      if (up === 'TRUE') return { k: 'bool', v: true }
      if (up === 'FALSE') return { k: 'bool', v: false }
      if (peekOp(':')) {
        p++
        if (p >= toks.length || toks[p].t !== 'word') throw new Bad()
        const w2 = toks[p++].v
        const u2 = w2.toUpperCase()
        if (u2 === 'TRUE' || u2 === 'FALSE' || peekOp('(')) throw new Bad()
        return { k: 'range', a: t.v, b: w2 }
      }
      return { k: 'ref', a: t.v }
    }
    throw new Bad()
  }

  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (x) {
    if (x instanceof Bad) return null
    throw x
  }
}

function misplaced(node, isArg) {
  switch (node.k) {
    case 'range': return !isArg
    case 'bin': return misplaced(node.l, false) || misplaced(node.r, false)
    case 'un': case 'group': return misplaced(node.e, false)
    case 'call': return node.args.some((a) => misplaced(a, true))
    default: return false
  }
}

function rangeCells(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const out = []
  for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push({ col: c, row: r })
  return out
}

function colName(c) {
  if (c <= 26) return String.fromCharCode(64 + c)
  const k = c - 27
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}

function collectRefs(node, set) {
  switch (node.k) {
    case 'ref': { const a = parseAddr(node.a); if (a) set.set(a.key, a); break }
    case 'range': {
      const cs = rangeCells(node.a, node.b)
      if (cs) for (const c of cs) { const key = colName(c.col) + c.row; set.set(key, { col: c.col, row: c.row, key }) }
      break
    }
    case 'bin': collectRefs(node.l, set); collectRefs(node.r, set); break
    case 'un': case 'group': collectRefs(node.e, set); break
    case 'call': node.args.forEach((a) => collectRefs(a, set)); break
  }
}

function classify(cell) {
  if (cell.parsed) return cell.parsed
  const c = cell.content
  let r
  if (c[0] === '=') {
    const ast = parseFormula(c.slice(1))
    if (!ast) r = { kind: 'value', value: err('#ERR!') }
    else if (misplaced(ast, false)) r = { kind: 'formula', ast, bad: true }
    else r = { kind: 'formula', ast }
  } else if (c === '') r = { kind: 'value', value: 0 }
  else if (NUM_RE.test(c)) r = { kind: 'value', value: Number(c) }
  else if (ERRORS.includes(c)) r = { kind: 'value', value: err(c) }
  else r = { kind: 'value', value: c }
  cell.parsed = r
  r.grammarOk = !(r.kind === 'value' && c[0] === '=')
  return r
}

export function depsOf(cell) {
  const k = classify(cell)
  if (k.kind !== 'formula') return []
  const set = new Map()
  collectRefs(k.ast, set)
  return [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row).map((a) => a.key)
}

// ---------- evaluation ----------
function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)

function num(v) {
  if (isErr(v)) return v
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return err('#VALUE!')
}
const fin = (n) => (Number.isFinite(n) ? n : err('#DIV/0!'))

export function evaluateAll(cells) {
  const byKey = new Map(cells.map((c) => [c.addr, c]))
  const memo = new Map()
  const busy = new Set()

  function cellValue(key) {
    if (memo.has(key)) return memo.get(key)
    const cell = byKey.get(key)
    if (!cell) return 0
    if (busy.has(key)) return err('#CYCLE!')
    busy.add(key)
    const k = classify(cell)
    let v
    if (k.kind === 'value') v = k.value
    else if (k.bad) v = err('#ERR!')
    else v = ev(k.ast)
    busy.delete(key)
    memo.set(key, v)
    return v
  }

  function refValue(word) {
    const a = parseAddr(word)
    return a ? cellValue(a.key) : err('#REF!')
  }

  // values contributed by one function argument
  function argValues(node) {
    if (node.k === 'range') {
      const cs = rangeCells(node.a, node.b)
      if (!cs) return [err('#REF!')]
      return cs.map((c) => cellValue(colName(c.col) + c.row))
    }
    return [ev(node)]
  }

  function call(node) {
    const n = node.args.length
    const name = node.name
    if (name === 'IF') {
      if (n !== 3) return err('#ERR!')
      const single = (a) => {
        const vs = argValues(a)
        return vs.length === 1 ? vs[0] : err('#ERR!')
      }
      const c = single(node.args[0])
      if (isErr(c)) return c
      let truth
      if (typeof c === 'boolean') truth = c
      else if (typeof c === 'number') truth = c !== 0
      else return err('#VALUE!')
      return single(node.args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      if (n !== 1) return err('#ERR!')
      const vs = argValues(node.args[0])
      if (vs.length !== 1) return err('#ERR!')
      const x = num(vs[0])
      return isErr(x) ? x : Math.abs(x)
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
    if (n < 1) return err('#ERR!')
    const vals = node.args.flatMap(argValues)
    const firstErr = vals.find(isErr)
    if (firstErr) return firstErr
    if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
    const nums = []
    for (const v of vals) {
      const x = num(v)
      if (isErr(x)) return x
      nums.push(x)
    }
    if (name === 'MIN') return Math.min(...nums)
    if (name === 'MAX') return Math.max(...nums)
    const total = nums.reduce((s, x) => s + x, 0)
    if (name === 'SUM') return fin(total)
    return fin(total / nums.length)
  }

  function ev(node) {
    switch (node.k) {
      case 'num': return node.v
      case 'bool': return node.v
      case 'group': return ev(node.e)
      case 'ref': return refValue(node.a)
      case 'range': return err('#ERR!')
      case 'call': return call(node)
      case 'un': {
        const x = num(ev(node.e))
        if (isErr(x)) return x
        return node.op === '-' ? -x : x
      }
      case 'bin': {
        const l = ev(node.l)
        const r = ev(node.r)
        if (['=', '<>', '<', '<=', '>', '>='].includes(node.op)) {
          if (isErr(l)) return l
          if (isErr(r)) return r
          let d
          if (rank(l) !== rank(r)) d = rank(l) - rank(r)
          else if (typeof l === 'number') d = l < r ? -1 : l > r ? 1 : 0
          else if (typeof l === 'string') d = cpCompare(l, r)
          else d = Number(l) - Number(r)
          switch (node.op) {
            case '=': return d === 0
            case '<>': return d !== 0
            case '<': return d < 0
            case '<=': return d <= 0
            case '>': return d > 0
            default: return d >= 0
          }
        }
        const a = num(l)
        if (isErr(a)) return a
        const b = num(r)
        if (isErr(b)) return b
        switch (node.op) {
          case '+': return fin(a + b)
          case '-': return fin(a - b)
          case '*': return fin(a * b)
          case '/': return b === 0 ? err('#DIV/0!') : fin(a / b)
          default: return fin(Math.pow(a, b))
        }
      }
    }
    return err('#ERR!')
  }

  const result = new Map()
  for (const c of cells) result.set(c.addr, cellValue(c.addr))
  return result
}

export function formatValue(v) {
  if (isErr(v)) return v.err
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}
"}

